        aws: FAKE_AWS_KEY,
        mixed: `${FAKE_GITHUB_TOKEN} text ${FAKE_AWS_KEY}`,
      },
    });

    const [admitted] = await rt.store.append([draft]);
    expect(admitted).toBeDefined();
    rt.close();

    // Byte-scan the closed DB
