      expect(bytes.includes(Buffer.from("ghp_", "utf8"))).toBe(false);
      expect(bytes.includes(Buffer.from(FAKE_AWS_KEY, "utf8"))).toBe(false);
      expect(bytes.includes(Buffer.from("AKIA", "utf8"))).toBe(false);
